import random

def handle_conversation(message: str) -> str:
    message = message.lower().strip()

    responses = [
        "I'm doing well, thanks for asking! It's great to hear from you. What's on your mind today?",
        "Hey! I'm hanging in there and ready for a good chat. How has your day been so far?",
        "Doing great! I always appreciate a friendly check-in. What would you like to talk about?",
        "I'm doing awesome. I'm all ears—what's going on in your world?"
    ]

    if any(phrase in message for "how" in message or "talk" in message or "doing" in message):
        return random.choice(responses)

    return "I'm here and ready to chat. Tell me more about what's on your mind!"

if __name__ == "__main__":
    user_input = "how u doing today? just wanted to talk"
    print(f"User: {user_input}")
    print(f"Response: {handle_conversation(user_input)}")
